functions=[node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name in ('request','integration_tick')]
assert len(functions)==2
compiled=compile(ast.Module(body=functions,type_ignores=[]),'actual-joint-observer-request-and-tick','exec')
results=[]
for mode in ('quiet_then_ready','resources_unsafe','missing_release_proof'):
 clock=[0.];mux=ThreeWayVelocityMux();requests=[];enabled=[]
 def future(value):return SimpleNamespace(done=lambda:True,result=lambda:value)
 class Status:
  def service_is_ready(self):return True
  def call_async(self,req):
   v=mux.output(now=clock[0]);packet={'owner':mux.owner,'last_output':[v.linear,v.angular],'last_lease_revocation':None}
   return future(SimpleNamespace(ok=True,status_json=json.dumps(packet)))
 class Control:
  def service_is_ready(self):return True
  def call_async(self,req):
   requests.append(clock[0]);assert req.operation=='claim_dock'
   try:
    mux.claim_dock(now=clock[0],nav_released=mode!='missing_release_proof',prior_terminal_uuid=None)
    reply=SimpleNamespace(ok=True,state=mux.owner,error='')
   except ReactiveMuxError as exc:reply=SimpleNamespace(ok=False,state=mux.owner,error=str(exc))
   return future(reply)
 integration={'snapshot':None,'status_future':None,'request_future':None,'request_operation':None,'last_status_poll':-1.,'calls':[],'claimed':False,'enabled':False,'released':False,'post_release_snapshot':None}
 namespace={'integration':integration,'control':Control(),'status':Status(),'ControlCleaning':SimpleNamespace(Request=SimpleNamespace),'GetCleaningStatus':SimpleNamespace(Request=SimpleNamespace),'Bool':SimpleNamespace,'json':json,'n':SimpleNamespace(sweep_complete=True,_sim_now=lambda:clock[0]),'latest':{'phase':SimpleNamespace(data='IDLE')},'enable':SimpleNamespace(publish=lambda msg:enabled.append((clock[0],msg.data)))}
 exec(compiled,namespace);caught=None
 for step in range(201):
  clock[0]=step/100.
  health=MotionHealth(True,mode!='resources_unsafe',True,True,True,True,None,True,True)
  mux.observe_odom(now=clock[0],linear_mps=0.,angular_rps=0.);mux.observe_health(now=clock[0],proof=health)
  try:namespace['integration_tick'](clock[0])
  except RuntimeError as exc:caught=str(exc);break
  if enabled:break
  assert mux.output(now=clock[0]).linear==0. and mux.output(now=clock[0]).angular==0.
 checks={'no_early_enable':not enabled or enabled[0][0]>=mux.quiet_required,
         'coalesced_requests':all(b-a>=.09 for a,b in zip(requests,requests[1:]))}
 if mode=='quiet_then_ready':checks.update({'no_fatal_not_ready':caught is None,'eventual_authorized_enable':bool(enabled) and mux.owner==mux.DOCK})
 elif mode=='resources_unsafe':checks.update({'keeps_waiting':caught is None,'never_enabled':not enabled and mux.owner==mux.STOP})
 else:checks.update({'real_error_retained':caught is not None and 'Nav2 release witness' in caught,'never_enabled':not enabled and mux.owner==mux.STOP})
 row={'mode':mode,'checks':checks,'pass':all(checks.values()),'error':caught,'requests':requests,'enable':enabled,'owner':mux.owner};results.append(row)
print('OOMWOO_HANDOFF_SMALL '+json.dumps(results),flush=True)
assert all(row['pass'] for row in results), 'observer must wait for actual mux authorization'

